<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import Icon from './components/Icon.vue'
import Dashboard5 from './views/Dashboard5.vue'
import Dashboard6 from './views/Dashboard6.vue'
import Dashboard7 from './views/Dashboard7.vue'
import Dashboard8 from './views/Dashboard8.vue'
import Dashboard9 from './views/Dashboard9.vue'
import Dashboard10 from './views/Dashboard10.vue'
const validDashboard = () => { const n = Number(location.hash.match(/dashboard-(\d+)/)?.[1]); return n >= 5 && n <= 10 ? n : 5 }
const dashboard = ref(validDashboard()), collapsed = ref(false), light = ref(false), density = ref(false), notificationOpen = ref(false), workspaceOpen = ref(false), searchOpen = ref(false), search = ref(''), modal = ref(null), field = ref(''), secondField = ref(''), toast = ref(''), dismissed = ref(false)
let toastTimer
const dashboards = { 5: Dashboard5, 6: Dashboard6, 7: Dashboard7, 8: Dashboard8, 9: Dashboard9, 10: Dashboard10 }
const descriptions = {5:'Web analytics',6:'Finance overview',7:'Marketing',8:'Store operations',9:'Commerce growth',10:'Observability'}
const component = computed(() => dashboards[dashboard.value])
const title = computed(() => dashboard.value >= 9 ? 'Overview' : 'Dashboard')
const groups = computed(() => {
 if (dashboard.value === 5) return [{title:'Explore',items:[['dashboard','Dashboard'],['events','Events'],['funnel','Funnels'],['retention','Retention'],['branch','Flows']]},{title:'Audiences',items:[['users','Segments'],['cohort','Cohorts'],['user','Profiles']]},{title:'Configure',items:[['plug','Integrations']]}]
 if (dashboard.value === 9) return [{items:[['dashboard','Overview'],['analytics','Sales'],['analytics','Analytics'],['database','Storage']]},{items:[['cart','Orders'],['box','Products'],['users','Customers'],['campaign','Marketing']]},{items:[['plug','Integrations'],['key','API Keys'],['activity','Activity'],['terminal','Logs']]},{items:[['layers','Resources']]}]
 if (dashboard.value === 10) return [{title:'Platform',items:[['dashboard','Overview'],['rocket','Deployments'],['analytics','Analytics'],['database','Storage'],['layers','Resources']]},{title:'Developer',items:[['plug','Integrations'],['key','API Keys'],['terminal','Logs']]}]
 if (dashboard.value === 7) return [{title:'Platform',items:[['dashboard','Dashboard'],['analytics','Analytics'],['box','Projects'],['plug','Integrations']]},{title:'System',items:[['settings','Settings']]}]
 return [{title:dashboard.value === 6 ? 'Platform' : '',items:[['dashboard','Dashboard'],['calendar','Content Calendar'],['campaign','Campaigns'],['analytics','Analytics'],['users','Team'],['plug','Integrations']]}]
})
const filteredDashboards = computed(() => Object.entries(descriptions).filter(([n,d]) => (`dashboard ${n} ${d}`).toLowerCase().includes(search.value.toLowerCase())))
watch(dashboard, n => { location.hash = `dashboard-${n}`; document.title = `Dashboard ${n} · ${descriptions[n]}`; collapsed.value = false; dismissed.value = false; notificationOpen.value = false; workspaceOpen.value = false; document.querySelector('.main-scroll')?.scrollTo(0,0) })
function hashChange() { dashboard.value = validDashboard() }
function notify(message) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = '', 3500) }
function openAction(action) { modal.value = typeof action === 'string' ? {title: action, body: `${action} is available in this sample workspace.`} : action; field.value = action.amount || ''; secondField.value = '' }
function saveModal() {
 if (!String(field.value).trim()) return
 if (modal.value.type === 'invite' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value)) return
 modal.value.onSave?.(field.value)
 notify(modal.value.type === 'invite' ? `Invitation created for ${field.value}` : modal.value.type === 'budget' ? `Budget saved: $${Number(field.value).toLocaleString()}` : `${modal.value.type === 'product' ? 'Product' : 'Campaign'} “${field.value}” created`)
 modal.value = null
}
function download(data) {
 const rows = [data.headings,...data.rows].map(row => row.map(cell => '"'+String(cell).replaceAll('"','""')+'"').join(',')).join('\n')
 const url = URL.createObjectURL(new Blob([rows],{type:'text/csv;charset=utf-8;'}))
 const a = document.createElement('a'); a.href = url; a.download = data.name + '.csv'; a.click(); URL.revokeObjectURL(url); notify('Report downloaded')
}
function keyboard(e) { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); searchOpen.value = !searchOpen.value } if(e.key === 'Escape') { searchOpen.value = false; modal.value = null; notificationOpen.value = false; workspaceOpen.value = false } }
onMounted(() => { addEventListener('hashchange',hashChange); addEventListener('keydown',keyboard) })
onUnmounted(() => { removeEventListener('hashchange',hashChange); removeEventListener('keydown',keyboard); clearTimeout(toastTimer) })
</script>
<template>
  <div class="app-shell" :class="['shell-' + dashboard, {collapsed, light, 'compact-density':density}]">
    <aside class="sidebar">
      <div class="brand-row"><a href="#dashboard-5" class="brand" aria-label="Dashboard home"><Icon name="dashboard" :size="19"/><span>Workspace</span></a><button v-if="dashboard !== 9" class="text-button collapse-brand" aria-label="Toggle sidebar" @click="collapsed=!collapsed"><Icon name="panel"/></button></div>
      <div v-if="[6,7,8,10].includes(dashboard)" class="workspace-wrap"><button class="workspace-button" @click="workspaceOpen=!workspaceOpen"><span class="workspace-orb"></span><span>{{dashboard === 6 || dashboard === 8 ? 'Your workspace' : 'Workspace'}}</span><small v-if="dashboard===10" class="neutral-pill">free</small><Icon name="down" :size="13"/></button><div v-if="workspaceOpen" class="workspace-menu"><small>Workspace</small><button @click="workspaceOpen=false"><span class="workspace-orb"></span>Your workspace<Icon name="done" :size="14"/></button><button @click="workspaceOpen=false;openAction({title:'Create workspace',type:'campaign'})"><Icon name="plus"/>Create workspace</button></div></div>
      <button v-if="dashboard === 5 || dashboard === 8" class="sidebar-search search-field" @click="searchOpen=true"><Icon name="search"/><span>Search…</span><kbd>⌘</kbd><kbd>K</kbd></button>
      <nav aria-label="Main navigation"><div v-for="(group,gi) in groups" :key="gi" class="nav-group"><p v-if="group.title" class="nav-label">{{group.title}}</p><button v-for="(item,i) in group.items" :key="item[1]" :class="['nav-link',{active:gi===0 && i===0}]" :title="item[1]" @click="gi===0 && i===0 ? null : openAction({title:item[1],body: `${item[1]} in your Workspace workspace. This reproduction focuses on the dashboard overview.`})"><Icon :name="item[0]"/><span>{{item[1]}}</span><Icon v-if="['Projects','Resources'].includes(item[1])" name="right" :size="13" class="nav-chevron"/></button></div></nav>
      <div class="sidebar-bottom">
        <div v-if="![8,9].includes(dashboard) && !dismissed" class="sidebar-promo" :class="{'edge-promo':dashboard===10}"><button class="promo-dismiss text-button" aria-label="Dismiss update" @click="dismissed=true"><Icon name="close" :size="12"/></button><template v-if="dashboard===5"><h4>Real-time funnels</h4><p>Build and analyze conversion funnels with live event streaming in real-time.</p></template><template v-else-if="dashboard===10"><h4>Edge deployments are here</h4><p>Deploy to 30+ regions with automatic failover and zero-config routing</p><div class="edge-art" aria-hidden="true"><i></i><i></i></div></template><template v-else><small class="update-label">UPDATE</small><h4>{{dashboard===6 ? 'What’s new' : 'Product update'}}</h4><p>{{dashboard===6 ? 'Latest fixes and new features.' : 'Performance boosts and UI polish.'}}</p></template><button v-if="dashboard!==10" class="text-button" @click="openAction({title:'Product update',body:'Performance improvements, faster charts, and a refreshed dashboard experience are now available.'})">{{dashboard===5 ? 'Read more' : 'Learn more'}}</button></div>
        <div v-if="dashboard===5" class="sidebar-footer-icons"><button class="text-button" aria-label="Toggle theme" @click="light=!light"><Icon name="globe"/></button><button class="text-button" aria-label="Settings" @click="openAction({title:'Appearance',type:'customize'})"><Icon name="settings"/></button></div>
        <template v-else><button class="nav-link" title="Support" @click="openAction({title:'Support',body:'For help with this demo, use the dashboard selector to explore the six recreated views.'})"><Icon name="help"/><span>{{[6,7].includes(dashboard) ? 'Help Center' : 'Support'}}</span></button><button class="nav-link" :title="[6,7].includes(dashboard) ? 'Documentation' : 'Settings'" @click="openAction({title:[6,7].includes(dashboard) ? 'Documentation' : 'Settings',type:'customize'})"><Icon :name="[6,7].includes(dashboard) ? 'book' : 'settings'"/><span>{{[6,7].includes(dashboard) ? 'Documentation' : 'Settings'}}</span></button></template>
        <button v-if="dashboard===6" class="profile-button" @click="openAction({title:'Shaban Haider',body:'shaban@example.com · Your workspace workspace'})"><span class="avatar light-avatar">SH</span><span>Shaban Haider<small>shaban@example.com</small></span><Icon name="down" :size="13"/></button>
        <div v-if="dashboard===8" class="copyright"><small>© Your workspace</small><button class="text-button" aria-label="Toggle sidebar" @click="collapsed=!collapsed"><Icon name="panel"/></button></div>
      </div>
    </aside>
    <main class="main-shell">
      <header class="topbar" :class="{ 'finance-topbar': dashboard===6 }"><div class="breadcrumb"><button v-if="dashboard!==9" class="text-button topbar-collapse" aria-label="Toggle sidebar" @click="collapsed=!collapsed"><Icon name="panel"/></button><span class="breadcrumb-divider" v-if="dashboard===7"></span><Icon v-if="dashboard!==5 && dashboard!==6" name="dashboard" :size="14"/><span>{{dashboard===6 ? 'Workspace overview' : title}}</span></div><div class="topbar-actions"><label class="dashboard-picker"><span class="sr-only">Choose dashboard</span><select v-model="dashboard" aria-label="Choose dashboard"><option v-for="n in [5,6,7,8,9,10]" :key="n" :value="n">Dashboard {{n}}</option></select></label><button v-if="[7,9,10].includes(dashboard)" class="top-search" aria-label="Open search" @click="searchOpen=true"><Icon name="search"/><span v-if="dashboard===10">Find</span><kbd>{{dashboard===7 ? '⌘ K' : dashboard===10 ? 'F' : '/'}}</kbd></button><button v-if="dashboard===5" class="icon-button help-button" aria-label="Help" @click="openAction({title:'Dashboard help',body:'Explore six dashboard layouts using the dashboard selector. Hover charts for values, search transactions, change reporting periods, and export reports.'})"><Icon name="help"/></button><button class="icon-button notification-button" aria-label="Notifications" @click="notificationOpen=!notificationOpen"><Icon name="bell"/><i></i></button><button class="avatar light-avatar header-avatar" aria-label="Open profile" @click="openAction({title:'Shaban Haider',body:'shaban@example.com · Your workspace'})">SH</button></div></header>
      <div class="main-scroll" :key="dashboard"><component :is="component" @action="openAction" @customize="openAction({title:'Customize dashboard',type:'customize'})" @download="download"/></div>
    </main>
    <div v-if="notificationOpen" class="notification-popover"><div class="section-title"><h3>Notifications</h3><button class="text-button" @click="notificationOpen=false" aria-label="Close notifications"><Icon name="close"/></button></div><div><i class="status-dot"></i><span>Weekly report is ready<small>Your latest dashboard report is available.</small></span></div><div><i class="status-dot stable"></i><span>Workspace updated<small>Your team’s changes have been saved.</small></span></div><button class="full-button" @click="notificationOpen=false;notify('All notifications marked as read')">Mark all as read</button></div>
    <div v-if="searchOpen" class="modal-backdrop" @click.self="searchOpen=false"><section class="command-dialog" role="dialog" aria-modal="true" aria-label="Search dashboards"><label class="command-input"><Icon name="search"/><input v-model="search" autofocus placeholder="Search dashboards…" aria-label="Search dashboards"><button class="text-button" @click="searchOpen=false">Esc</button></label><p>Dashboards</p><button v-for="[n,desc] in filteredDashboards" :key="n" @click="dashboard=Number(n);searchOpen=false;search=''"><Icon name="dashboard"/><span>Dashboard {{n}}<small>{{desc}}</small></span><Icon name="arrow"/></button><div v-if="!filteredDashboards.length" class="empty-state">No dashboards found.</div></section></div>
    <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section class="dialog" role="dialog" aria-modal="true" :aria-label="modal.title"><div class="section-title"><h2>{{modal.title}}</h2><button class="text-button" aria-label="Close dialog" @click="modal=null"><Icon name="close"/></button></div><template v-if="modal.type==='customize'"><p>Adjust your dashboard view.</p><label class="setting-row"><span>Compact spacing</span><input type="checkbox" v-model="density"></label><label class="setting-row"><span>Collapse sidebar</span><input type="checkbox" v-model="collapsed"></label><label class="setting-row"><span>Light appearance</span><input type="checkbox" v-model="light"></label><button class="primary-button" @click="modal=null">Done</button></template><form v-else-if="['invite','product','campaign','budget'].includes(modal.type)" @submit.prevent="saveModal"><p>{{modal.type==='invite' ? 'Invite a teammate to collaborate in your workspace.' : modal.type==='budget' ? 'Set the budget for this reporting period.' : 'Add the details below to create a local demo entry.'}}</p><label class="form-label">{{modal.type==='invite' ? 'Email address' : modal.type==='budget' ? 'Budget amount' : 'Name'}}<input v-model="field" :type="modal.type==='invite' ? 'email' : modal.type==='budget' ? 'number' : 'text'" :min="modal.type==='budget' ? 0 : undefined" required :placeholder="modal.type==='invite' ? 'name@company.com' : modal.type==='budget' ? '50000' : 'Enter a name'"></label><label v-if="modal.type==='product' || modal.type==='campaign'" class="form-label">Description<input v-model="secondField" placeholder="Add a description"></label><div class="dialog-actions"><button type="button" @click="modal=null">Cancel</button><button class="primary-button" type="submit">{{modal.type==='invite' ? 'Invite member' : modal.type==='budget' ? 'Save budget' : 'Create'}}</button></div></form><template v-else><p class="dialog-body">{{modal.body}}</p><button class="primary-button" @click="modal=null">Close</button></template></section></div>
    <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="check"/>{{toast}}</div></Transition>
  </div>
</template>
